mapper.select:
SELECT a.id, a.alarm_code AS alarmCode, p.pile_code AS pileCode, p.model AS pileName, a.station_id AS stationId, s.station_name AS stationName, a.fault_type AS faultType, a.alarm_level AS alarmLevel, a.alarm_time AS alarmTime, a.handler_id AS handleUser, u.nickname AS handleUserName, a.status AS alarmStatus, a.handle_result AS disposeMeasure, a.remark, a.create_time AS createTime, a.update_time AS updateTime FROM pile_alarm a LEFT JOIN charging_pile p ON a.pile_id = p.id LEFT JOIN charging_station s ON p.station_id = s.id LEFT JOIN sys_user u ON a.handler_id = u.id
a.deleted = 0
AND a.alarm_code LIKE CONCAT('%', #{reqVO.alarmCode}, '%')
AND p.station_id = #{reqVO.stationId}
AND a.fault_type = #{reqVO.faultType}
AND a.alarm_level = #{reqVO.alarmLevel}
AND a.status = #{reqVO.alarmStatus}
AND a.alarm_time >= #{reqVO.alarmTimeStart}
AND a.alarm_time <= #{reqVO.alarmTimeEnd}

SELECT
pa.fault_type AS name,
COUNT(pa.id) AS value
FROM pile_alarm pa
WHERE pa.deleted = 0

    AND pa.alarm_time >= #{startTime}


    AND pa.alarm_time <= #{endTime}


    AND pa.station_id = #{stationId}

GROUP BY pa.fault_type
ORDER BY value DESC

SELECT SUM(CASE WHEN pa.status = '未派单' THEN 1 ELSE 0 END) AS unDisCount, SUM(CASE WHEN pa.status = '已派单' THEN 1 ELSE 0 END) AS disCount, SUM(CASE WHEN pa.status = '处置中' THEN 1 ELSE 0 END) AS handlingCount, SUM(CASE WHEN pa.status = '已销单' THEN 1 ELSE 0 END) AS closedCount, COUNT(pa.id) AS totalCount FROM pile_alarm pa LEFT JOIN charging_pile cp ON pa.pile_id = CONVERT(cp.id USING utf8mb4) COLLATE utf8mb4_general_ci AND cp.deleted = 0 LEFT JOIN charging_station cs ON CONVERT(pa.station_id USING utf8mb4) = CONVERT(cs.id USING utf8mb4) AND cs.deleted = 0 WHERE pa.deleted = 0
AND pa.alarm_time >= #{startTime}
AND pa.alarm_time <= #{endTime}
AND pa.station_id = #{stationId}
